# Uji M3: grup, akses board per unit/grup/orang, Editor, penugasan ke grup dan orang.
UID=lambda n: "00000000-0000-0000-0000-0000000000"+U[n]
A="a0000000-0000-0000-0000-00000000000a"; C="c0000000-0000-0000-0000-00000000000c"
def pb(title): return f"(select p.id from playbooks p where p.name='{title}')"
cardA="(select id from cards where title='Card PB Lib Board A')"
sh(db,"update profiles set active=true")
sh(db,"insert into groups (holding_id,name) values ('bejo','Bejo grup')")
print('--- M3 grup')
expect('Ayu buat grup di SIB','ayu',f"insert into groups (holding_id,name,created_by) values ('sib','Audit','{UID('ayu')}'); select count(*) from groups where name='Audit'",1)
expect('Ayu TIDAK bisa buat grup di BEJO','ayu',f"insert into groups (holding_id,name) values ('bejo','X')",err=True)
expect('Dimas TIDAK bisa buat grup','dimas',"insert into groups (holding_id,name) values ('sib','Y')",err=True)
expect('Dimas tidak lihat grup yang bukan miliknya','dimas',cnt('groups'),0)
expect('Ayu tambah Rudi ke grup Audit','ayu',f"insert into group_members select id,'{UID('rudi')}' from groups where name='Audit'; select count(*) from group_members",1)
expect('Anggota harus punya keanggotaan di holding grup (Fajar BEJO ke grup SIB)','ayu',f"insert into group_members select id,'{UID('fajar')}' from groups where name='Audit'",err=True)
expect('Rudi lihat grup Audit karena anggotanya','rudi',cnt('groups'),1)
expect('Rudi tidak bisa menambah anggota','rudi',f"insert into group_members select id,'{UID('dimas')}' from groups where name='Audit'",err=True)
expect('Nama grup unik per holding (tanpa beda huruf besar)','ayu',"insert into groups (holding_id,name) values ('sib','audit')",err=True)
print('--- M3 akses board: sebelum dipersempit')
expect('Dimas lihat board A','dimas',cnt('boards',f"id='{A}'"),1)
expect('Rudi lihat board A','rudi',cnt('boards',f"id='{A}'"),1)
print('--- M3 akses board: persempit ke unit')
expect('Ayu persempit board A ke unit Operasional','ayu',f"insert into board_access (board_id,holding_id,subject_type,unit,role,created_by) values ('{A}','sib','unit','Operasional','pembaca','{UID('ayu')}'); select count(*) from board_access",1)
expect('Dimas (Operasional) tetap lihat board A','dimas',cnt('boards',f"id='{A}'"),1)
expect('Rudi (Finance) tidak lagi lihat board A','rudi',cnt('boards',f"id='{A}'"),0)
expect('Rudi tidak lihat library board A','rudi',cnt('libraries',f"board_id='{A}'"),0)
expect('Rudi tidak lihat card board A','rudi',cnt('cards',"title='Card PB Lib Board A'"),0)
expect('Dua Holding (unit kosong) tidak lihat board A','dua',cnt('boards',f"id='{A}'"),0)
expect('Ayu (admin SOP SIB) tetap lihat board A','ayu',cnt('boards',f"id='{A}'"),1)
expect('Board C (tanpa pembatasan) tetap terlihat Rudi','rudi',cnt('boards',f"id='{C}'"),1)
print('--- M3 akses board: grup dan orang')
expect('Ayu tambah grup Audit','ayu',f"insert into board_access (board_id,holding_id,subject_type,group_id,role) select '{A}','sib','group',id,'pembaca' from groups where name='Audit'; select count(*) from board_access",2)
expect('Rudi (anggota grup Audit) lihat board A','rudi',cnt('boards',f"id='{A}'"),1)
expect('Ayu tambah orang Dua Holding','ayu',f"insert into board_access (board_id,holding_id,subject_type,profile_id,role) values ('{A}','sib','user','{UID('dua')}','pembaca'); select count(*) from board_access",3)
expect('Dua Holding lihat board A','dua',cnt('boards',f"id='{A}'"),1)
expect('Orang di luar holding tidak bisa dijadikan pembaca (Fajar BEJO di SIB)','ayu',f"insert into board_access (board_id,holding_id,subject_type,profile_id,role) values ('{A}','sib','user','{UID('fajar')}','pembaca')",err=True)
expect('Grup holding lain tidak bisa dipakai di SIB','dhaka',f"insert into board_access (board_id,holding_id,subject_type,group_id,role) select '{A}','sib','group',id,'pembaca' from groups where name='Bejo grup'",err=True)
expect('Pembaca tidak boleh di holding PEOPLE','dhaka',f"insert into board_access (board_id,holding_id,subject_type,unit,role) values ('{A}','people','unit','HR','pembaca')",err=True)
expect('Holding yang tidak dibuka untuk board tidak bisa dipakai (BEJO di board A)','dhaka',f"insert into board_access (board_id,holding_id,subject_type,unit,role) values ('{A}','bejo','unit','Gudang','pembaca')",err=True)
expect('Ayu TIDAK bisa atur akses board C (ada BEJO)','ayu',f"insert into board_access (board_id,holding_id,subject_type,unit,role) values ('{C}','sib','unit','Finance','pembaca'); select count(*) from board_access where board_id='{C}'",err=True)
expect('Dimas tidak bisa membaca daftar akses','dimas',cnt('board_access'),0)
expect('Dimas tidak bisa menambah akses','dimas',f"insert into board_access (board_id,holding_id,subject_type,unit,role) values ('{A}','sib','unit','Finance','pembaca')",err=True)
expect('Rudi tidak bisa menambah akses untuk dirinya','rudi',f"insert into board_access (board_id,holding_id,subject_type,profile_id,role) values ('{A}','sib','user','{UID('rudi')}','pembaca')",err=True)
print('--- M3 Editor')
sh(db,f"insert into admin_access values ('{UID('intan')}','sib','sop')")
expect('Intan (admin SIB juga) bisa ubah card board A sebelum ada daftar Editor','intan',"update cards set title='Draf A3' where title='Draf A2'; select count(*) from cards where title='Draf A3'",1)
expect('Editor harus admin: Dimas ditolak','dhaka',f"insert into board_access (board_id,holding_id,subject_type,profile_id,role) values ('{A}','people','user','{UID('dimas')}','editor')",err=True)
expect('Editor harus punya akses SOP: Fajar ditolak','dhaka',f"insert into board_access (board_id,holding_id,subject_type,profile_id,role) values ('{A}','people','user','{UID('fajar')}','editor')",err=True)
expect('Dhaka jadikan Ayu Editor board A','dhaka',f"insert into board_access (board_id,holding_id,subject_type,profile_id,role) values ('{A}','people','user','{UID('ayu')}','editor'); select count(*) from board_access where role='editor'",1)
expect('Setelah ada daftar Editor, Intan tidak bisa ubah card board A','intan',"update cards set title='Draf A4' where title='Draf A3'; select count(*) from cards where title='Draf A4'",0)
expect('Ayu (Editor) tetap bisa ubah card board A','ayu',"update cards set title='Draf A5' where title='Draf A3'; select count(*) from cards where title='Draf A5'",1)
expect('Superadmin selalu bisa ubah','dhaka',"update cards set title='Draf A6' where title='Draf A5'; select count(*) from cards where title='Draf A6'",1)
expect('Intan tidak bisa menambah Editor','intan',f"insert into board_access (board_id,holding_id,subject_type,profile_id,role) values ('{A}','people','user','{UID('intan')}','editor')",err=True)
print('--- M3 penugasan ke grup dan orang')
expect('Dimas (tanpa penugasan) tidak bisa tandai baca card A','dimas',f"select mark_read({cardA})",err=True)
expect('Ayu tugaskan grup Audit di playbook board A','ayu',f"insert into playbook_requirements (playbook_id,holding_id,target_type,group_id,due_on) select {pb('PB Lib Board A')},'sib','group',id,'2026-12-20' from groups where name='Audit'; select count(*) from playbook_requirements where target_type='group'",1)
expect('Rudi (anggota Audit) bisa tandai baca card A','rudi',f"select mark_read({cardA}); select count(*) from read_receipts where profile_id='{UID('rudi')}'",1)
expect('Dimas tetap tidak bisa (hanya akses, bukan penugasan)','dimas',f"select mark_read({cardA})",err=True)
expect('Dimas tidak melihat penugasan grup orang lain','dimas',cnt('playbook_requirements',f"playbook_id={pb('PB Lib Board A')}"),0)
expect('Rudi melihat penugasan yang menyasarnya','rudi',cnt('playbook_requirements',f"playbook_id={pb('PB Lib Board A')}"),1)
expect('Ayu tugaskan orang: Dimas','ayu',f"insert into playbook_requirements (playbook_id,holding_id,target_type,profile_id,due_on) values ({pb('PB Lib Board A')},'sib','user','{UID('dimas')}','2026-12-25'); select count(*) from playbook_requirements where target_type='user'",1)
expect('Dimas kini bisa tandai baca card A','dimas',f"select mark_read({cardA}); select count(*) from read_receipts where profile_id='{UID('dimas')}' and card_id={cardA}",1)
expect('Penugasan ke orang tanpa akses board ditolak (Fajar BEJO)','ayu',f"insert into playbook_requirements (playbook_id,holding_id,target_type,profile_id,due_on) values ({pb('PB Lib Board A')},'sib','user','{UID('fajar')}','2026-12-25')",err=True)
sh(db,f"insert into memberships (profile_id,holding_id,unit) values ('{UID('fajar')}','sib','Gudang')")
expect('Penugasan ke orang yang punya keanggotaan tapi tidak lolos pembatasan board (Fajar unit Gudang) ditolak','ayu',f"insert into playbook_requirements (playbook_id,holding_id,target_type,profile_id,due_on) values ({pb('PB Lib Board A')},'sib','user','{UID('fajar')}','2026-12-25')",err=True)
expect('Penugasan grup holding lain ditolak','dhaka',f"insert into playbook_requirements (playbook_id,holding_id,target_type,group_id,due_on) select {pb('PB Lib Board A')},'sib','group',id,'2026-12-20' from groups where name='Bejo grup'",err=True)
expect('Dimas tidak bisa menulis penugasan','dimas',f"insert into playbook_requirements (playbook_id,holding_id,due_on) values ({pb('PB Lib Board A')},'sib','2026-12-01')",err=True)
print('--- M3 mencabut akses')
expect('Ayu cabut akses unit Operasional','ayu',f"delete from board_access where unit='Operasional'; select count(*) from board_access where subject_type='unit'",0)
expect('Dimas masih lihat board A lewat penugasan? Tidak: akses ditentukan board_access, bukan penugasan','dimas',cnt('boards',f"id='{A}'"),0)
expect('Dimas tidak bisa tandai baca setelah akses dicabut walau masih ditugaskan','dimas',f"select mark_read({cardA})",err=True)
expect('Penugasan Dimas tidak muncul lagi (playbook tak terlihat)','dimas',cnt('playbooks',f"id={pb('PB Lib Board A')}"),0)
print('--- M3 audit')
expect('Pemberian akses board tercatat di audit SIB','dhaka',cnt('audit_log',"action='board.access.grant' and holding_id='sib'"),3)
expect('Pencabutan akses tercatat','dhaka',cnt('audit_log',"action='board.access.revoke'"),1)
expect('Penugasan tercatat (satu dari fixture, dua dari uji)','dhaka',cnt('audit_log',"action='sop.assign'"),3)
